enum class RobotState {
    DISABLED,
    AUTONOMOUS,
    TELEOP
}

fun describe(state: RobotState): String {
    return when (state) {
        RobotState.DISABLED -> "Robot is disabled"
        RobotState.AUTONOMOUS -> "Robot is running autonomously"
        RobotState.TELEOP -> "Driver is in control"
    }
}

