import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testDisabled() {
        Assert.assertEquals("Robot is disabled", describe(RobotState.DISABLED))
    }

    @Test
    fun testAutonomous() {
        Assert.assertEquals("Robot is running autonomously", describe(RobotState.AUTONOMOUS))
    }

    @Test
    fun testTeleop() {
        Assert.assertEquals("Driver is in control", describe(RobotState.TELEOP))
    }

    @Test
    fun testEnumHasThreeValues() {
        Assert.assertEquals(3, RobotState.values().size)
    }
}
